135:   if (world.phase === 8) targets.push({ kind: 'push', x: tug.x, y: tug.y, label: 'AUTORIZAR SALIDA', icon: '➜' });
136:   if (world.carried) targets.push({ kind: 'drop', x: 460, y: 590, label: 'SOLTAR EQUIPAJE', icon: '↓' });
137:   let nearest = null, dmin = 76;
