205: function update(dt) {
206:   if (paused || world.finished) return;
207:   elapsed += dt; world.phaseTime += dt;
208:   if (toastTimer > 0 && (toastTimer -= dt) <= 0) ui.toast.classList.remove('show');
209:   let ix = (keys.arrowright || keys.d ? 1 : 0) - (keys.arrowleft || keys.a ? 1 : 0) + stick.x;
210:   let iy = (keys.arrowdown || keys.s ? 1 : 0) - (keys.arrowup || keys.w ? 1 : 0) + stick.y;
211:   let mag = Math.hypot(ix, iy); if (mag > 1) { ix /= mag; iy /= mag; mag = 1; }
212:   const speed = (sprinting ? 205 : 130) * (world.carried ? .72 : 1);
213:   player.vx = ix * speed; player.vy = iy * speed;
214:   let nx = player.x + player.vx * dt, ny = player.y + player.vy * dt;
215:   const planeDX = nx - world.plane.x, planeDY = ny - world.plane.y;
216:   if ((planeDX * planeDX) / (205 * 205) + (planeDY * planeDY) / (68 * 68) > 1.12) {
217:     player.x = clamp(nx, 55, 1450); player.y = clamp(ny, 310, 930);
218:   }
219:   // Equipment has a soft collision boundary; walking around remains easy on touch screens.
220:   for (const e of [stairs, belt, tug]) {
221:     const r = e === stairs ? 23 : 21;
222:     if (dist(player, e) < r && dist({ x: nx, y: ny }, e) < dist(player, e)) { nx = player.x; ny = player.y; }
223:   }
224:   if (mag > .08) { player.dir = Math.atan2(iy, ix); player.walk += dt * speed * .12; } else player.walk *= .86;
225:   // Resolve movement after soft equipment boundaries.
226:   const proposed = { x: nx, y: ny };
227:   if (Math.hypot(proposed.x - player.x, proposed.y - player.y) > 0.5) {
228:     const dpx = proposed.x - world.plane.x, dpy = proposed.y - world.plane.y;
229:     if ((dpx * dpx) / (205 * 205) + (dpy * dpy) / (68 * 68) > 1.12) { player.x = proposed.x; player.y = proposed.y; }
230:   }
231:   if (world.phase === 0) {
232:     world.plane.x = Math.min(760, world.plane.x + 235 * dt); world.plane.y = 430;
233:     if (world.plane.x >= 760) { world.plane.x = 760; if (world.phaseTime > 2.5) { setPhase(1); announce('Aeronave estacionada · coloca los calzos'); } }
234:   }
235:   moveEquipment(dt); moveAgents(dt); movePassengers(dt); moveBags(dt);
236:   if (world.phase === 2 && world.stairReady && world.beltReady && world.phaseTime > .8) { setPhase(3); announce('Equipos estabilizados · abre las bodegas'); }
237:   if (world.phase === 3 && world.unloaded >= world.bagCount && world.paxOut >= passengers.filter(p => p.type === 'arrival').length && !world.assistTriggered) {
238:     world.assistTriggered = true; const ap = passengers.find(p => p.assist);
239:     if (ap) { ap.state = 'needsHelp'; ap.x = 830; ap.y = 548; ap.target = { x: 830, y: 548 }; }
240:     setPhase(4); announce('Se requiere asistencia para un pasajero', true);
241:   }
242:   if (world.phase === 5 && world.paxIn >= passengers.filter(p => p.type === 'departure').length && world.loaded >= inboundBags.length && world.phaseTime > 2.5) {
243:     setPhase(6); announce('Embarque y carga completos · cierra las bodegas');
244:   }
245:   if (world.phase === 7 && stairs.state === 'park' && belt.state === 'park' && tug.state === 'park' && world.phaseTime > 1.3) {
246:     setPhase(8); announce('Plataforma despejada · solicita autorización de salida');
247:   }
248:   if (world.phase === 9) updatePushback(dt);
249:   const follow = world.phase === 9 ? world.plane.x : player.x + 80;
250:   cam.x = lerp(cam.x, follow, .055); cam.y = lerp(cam.y, world.phase === 9 ? 490 : player.y - 5, .045);
251:   cam.x = clamp(cam.x, 450, 1060); cam.y = clamp(cam.y, 350, 650);
252:   const focus = targetForInteraction();
253:   ui.interactLabel.textContent = focus ? focus.label : (world.carried ? 'SOLTAR' : 'INTERACTUAR');
254:   ui.interactIcon.textContent = focus ? focus.icon : (world.carried ? '↓' : '↗');
255:   ui.interact.style.opacity = focus ? '1' : '.76';
256:   ui.timer.textContent = fmt(elapsed); ui.bags.textContent = `${world.phase < 5 ? world.unloaded : world.loaded} / ${world.bagCount}`;
257:   ui.crew.textContent = `${agents.filter(a => !['standby', 'patrol'].includes(a.state)).length} activos`;
258:   ui.money.textContent = '$' + money.toLocaleString('en-US');
259: }
260: function moveEquipment(dt) {
261:   for (const e of [stairs, belt, tug]) {
262:     if (!['approach', 'return', 'deliver', 'pushApproach'].includes(e.state)) continue;
263:     let tx = e.tx, ty = e.ty;
264:     if (e.state === 'return') {
265:       if (e === stairs) { tx = 450; ty = 560; }
266:       if (e === belt) { tx = 420; ty = 625; }
267:       if (e === tug) { tx = 365; ty = 740; }
268:     }
269:     const d = Math.hypot(tx - e.x, ty - e.y), v = e === tug ? 65 : 48;
270:     if (d > 2) { e.x += (tx - e.x) / d * Math.min(d, v * dt); e.y += (ty - e.y) / d * Math.min(d, v * dt); }
271:     else {
272:       e.x = tx; e.y = ty;
273:       if (e === stairs && e.state === 'approach') { e.state = 'park'; world.stairReady = true; }
274:       else if (e === belt && e.state === 'approach') { e.state = 'park'; world.beltReady = true; }
275:       else if (e.state === 'return') e.state = 'park';
276:       else if (e.state === 'deliver') e.state = 'park';
277:       else if (e.state === 'pushApproach') e.state = 'connected';
278:     }
279:   }
280: }
281: function moveAgents(dt) {
282:   for (let i = 0; i < agents.length; i++) {
283:     const a = agents[i];
284:     if (a.state === 'patrol' && (!a.target || dist(a, a.target) < 10)) a.target = { x: rand(520, 960), y: rand(545, 670) };
285:     if (a.state === 'driveStairs') a.target = { x: stairs.x - 35, y: stairs.y + 24 };
286:     if (a.state === 'driveBelt') a.target = { x: belt.x - 40, y: belt.y + 24 };
287:     if (a.state === 'returnStairs') a.target = { x: stairs.x - 28, y: stairs.y + 25 };
288:     if (a.state === 'returnBelt') a.target = { x: belt.x - 36, y: belt.y + 25 };
289:     if (a.state === 'returnTug' || a.state === 'deliver') a.target = { x: tug.x - 24, y: tug.y + 22 };
290:     if (a.state === 'unload') a.target = { x: belt.x + 5, y: belt.y + 34 };
291:     if (a.state === 'signal') a.target = { x: 610 + i * 36, y: 570 + (i % 2) * 38 };
292:     if (a.target) {
293:       const dx = a.target.x - a.x, dy = a.target.y - a.y, d = Math.hypot(dx, dy);
294:       if (d > 5) { const v = a.state === 'signal' ? 28 : 42; a.x += dx / d * Math.min(d, v * dt); a.y += dy / d * Math.min(d, v * dt); a.dir = Math.atan2(dy, dx); a.walk = (a.walk || 0) + dt * 6; }
295:     }
296:     if (a.state === 'driveStairs' && world.stairReady) a.state = 'work';
297:     if (a.state === 'driveBelt' && world.beltReady) a.state = 'work';
298:     if (a.state === 'returnStairs' && stairs.state === 'park') a.state = 'standby';
299:     if (a.state === 'returnBelt' && belt.state === 'park') a.state = 'standby';
300:     if (a.state === 'returnTug' && tug.state === 'park') a.state = 'standby';
301:   }
302: }
303: function movePassengers(dt) {
304:   for (const p of passengers) {
305:     if (p.wait > 0) { p.wait -= dt; continue; }
306:     if (p.state === 'needsHelp' || p.state === 'arrived' || p.state === 'assisted') continue;
307:     const d = Math.hypot(p.target.x - p.x, p.target.y - p.y);
308:     if (d > 4) {
309:       const v = p.speed || 27; p.x += (p.target.x - p.x) / d * Math.min(d, v * dt);
310:       p.y += (p.target.y - p.y) / d * Math.min(d, v * dt); p.walk = (p.walk || 0) + dt * 7;
